import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Considerazioni generali","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/g_geometria-dello-spazio/ge/geba.md","filePath":"lezioni/g_geometria-dello-spazio/ge/geba.md"}`),a={name:`lezioni/g_geometria-dello-spazio/ge/geba.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="considerazioni-generali" tabindex="-1">Considerazioni generali <a class="header-anchor" href="#considerazioni-generali" aria-label="Permalink to “Considerazioni generali”">​</a></h1><p>Vediamo ora come definire la perpendicolarità fra una retta e un piano.</p><p>Logicamente, se noi prendiamo una retta che incida un piano, se questa è obliqua formerà tanti angoli diversi con le rette del piano passanti per il punto di incontro e tra questi potremo distinguerne due retti come si può facilmente vedere prendendo una penna ed il registro di classe e provando varie inclinazioni.</p><blockquote><p>In figura l&#39;angolo in blu è minore di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>90</mn><mo lspace="0em" rspace="0em">∘</mo></msup></mrow><annotation encoding="application/x-tex">90^{\\circ}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6741em;"></span><span class="mord">9</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∘</span></span></span></span></span></span></span></span></span></span></span></span> mentre l&#39;angolo in verde è di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mn>90</mn><mo lspace="0em" rspace="0em">∘</mo></msup></mrow><annotation encoding="application/x-tex">90^{\\circ}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6741em;"></span><span class="mord">9</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6741em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∘</span></span></span></span></span></span></span></span></span></span></span></span></p></blockquote><p>Tra tutte le posizioni della retta però ve ne sarà una in cui la retta stessa sarà perpendicolare a tutte le rette del piano passanti per il punto di incontro. Viene quindi spontaneo dare la seguente definizione:</p><p><strong>Si dice che una retta è perpendicolare ad un piano se è perpendicolare a tutte le rette del piano passanti per il loro punto di incontro</strong></p><p>Naturalmente per vedere se una retta è perpendicolare ad un piano non possiamo considerare tutte le rette passanti per il punto di incontro fra la retta ed il piano, pertanto dovremo prendere una scorciatoia cioè trovare un criterio che ci permetta di vedere con un numero finito di passaggi se una retta è effettivamente perpendicolare ad un piano.</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};